  1	"use client";
  2	
  3	import { useEffect, useState } from "react";
  4	import { usePathname } from "next/navigation";
  5	
  6	/**
  7	 * Google Analytics 4 – wird erst nach Einwilligung („Statistik“ im Cookie-Banner) geladen.
  8	 *
  9	 * Umgebungsvariable: NEXT_PUBLIC_GA_ID (Mess-ID, z. B. G-XXXXXXXXXX)
 10	 *
 11	 * - Vor der Einwilligung: kein Skript, keine Verbindung zu Google, keine Cookies.
 12	 * - Google Consent Mode v2: Standard „denied“, nach Einwilligung nur analytics_storage „granted“
 13	 *   (keine Werbe-/Personalisierungsfreigaben).
 14	 * - Widerruf: Messung wird sofort gestoppt und die _ga-Cookies werden gelöscht.
 15	 * - Seiten mit Einmal-Tokens (/scan, /fortsetzen, /angebot) und die Info-Bildschirme (/tv) werden nie gemessen;
 16	 *   von URL-Parametern werden nur utm_* übertragen.
 17	 */
 18	// Eigene GA4-Property für ÖkoInvest – ohne Mess-ID wird nichts geladen (nie die ID der DE-Seite)
 19	const GA_ID = process.env.NEXT_PUBLIC_GA_ID || null;
 20	const AUSGENOMMEN = /^\/(scan|fortsetzen|tv|angebot)(\/|$)/; // angebot: persönliche Einmalcodes der Akquise-Kampagnen
 21	
 22	export function statistikErlaubt() {
 23	  if (typeof document === "undefined") return false;
 24	  try {
 25	    const roh = document.cookie.split("; ").find((c) => c.startsWith("cookieConsent="));
 26	    if (!roh) return false;
 27	    return JSON.parse(decodeURIComponent(roh.slice("cookieConsent=".length))).googleAnalytics === true;
 28	  } catch {
 29	    return false;
 30	  }
 31	}
 32	
 33	function gtagVorbereiten() {
 34	  window.dataLayer = window.dataLayer || [];
 35	  if (!window.gtag) {
 36	    window.gtag = function () {
 37	      window.dataLayer.push(arguments);
 38	    };
 39	    window.gtag("consent", "default", {
 40	      analytics_storage: "denied",
 41	      ad_storage: "denied",
 42	      ad_user_data: "denied",
 43	      ad_personalization: "denied",
 44	    });
 45	  }
 46	}
 47	
 48	function laden() {
 49	  window[`ga-disable-${GA_ID}`] = false;
 50	  gtagVorbereiten();
 51	  window.gtag("consent", "update", { analytics_storage: "granted" });
 52	  if (window.ovGaGeladen) return;
 53	  window.ovGaGeladen = true;
 54	  window.gtag("js", new Date());
 55	  // Seitenaufrufe senden wir selbst (bereinigte URL, Ausnahmen) – daher send_page_view: false
 56	  window.gtag("config", GA_ID, { send_page_view: false, allow_google_signals: false, allow_ad_personalization_signals: false });
 57	  const s = document.createElement("script");
 58	  s.src = `https://www.googletagmanager.com/gtag/js?id=${GA_ID}`;
 59	  s.async = true;
 60	  document.head.appendChild(s);
 61	}
 62	
 63	function stoppen() {
 64	  window[`ga-disable-${GA_ID}`] = true;
 65	  if (window.gtag) window.gtag("consent", "update", { analytics_storage: "denied" });
 66	  // _ga und _ga_<ID> auf allen passenden Domain-Ebenen löschen
 67	  const teile = location.hostname.split(".");
 68	  const domains = ["", ...teile.map((_, i) => "." + teile.slice(i).join("."))];
 69	  document.cookie.split("; ").forEach((c) => {
 70	    const name = c.split("=")[0];
 71	    if (!/^_ga(_|$)/.test(name)) return;
 72	    domains.forEach((d) => {
 73	      document.cookie = `${name}=; Max-Age=0; path=/${d ? `; domain=${d}` : ""}`;
 74	    });
 75	  });
 76	}
 77	
 78	function seitenaufruf(pfad) {
 79	  if (!window.ovGaGeladen || window[`ga-disable-${GA_ID}`] || AUSGENOMMEN.test(pfad)) return;
 80	  const url = new URL(window.location.href);
 81	  const utm = new URLSearchParams();
 82	  url.searchParams.forEach((w, k) => {
 83	    if (/^utm_(source|medium|campaign|term|content)$/.test(k)) utm.set(k, w.slice(0, 100));
 84	  });
 85	  const q = utm.toString();
 86	  window.gtag("event", "page_view", {
 87	    page_location: `${url.origin}${pfad}${q ? `?${q}` : ""}`,
 88	    page_path: pfad,
 89	    page_title: document.title,
 90	  });
 91	}
 92	
 93	export default function GoogleAnalytics() {
 94	  const pfad = usePathname();
 95	  const [erlaubt, setErlaubt] = useState(null); // null = noch nicht geprüft
 96	
 97	  useEffect(() => {
 98	    const pruefen = () => setErlaubt(statistikErlaubt());
 99	    pruefen();
100	    window.addEventListener("ov-consent", pruefen);
101	    return () => window.removeEventListener("ov-consent", pruefen);
102	  }, []);
103	
104	  useEffect(() => {
105	    if (!GA_ID) return;
106	    if (erlaubt) laden();
107	    else if (erlaubt === false) stoppen(); // auch alte _ga-Cookies nach einem Widerruf entfernen
108	  }, [erlaubt]);
109	
110	  useEffect(() => {
111	    if (GA_ID && erlaubt) seitenaufruf(pfad);
112	  }, [erlaubt, pfad]);
113	
114	  return null;
115	}
116	// src/lib/herkunft.js
117	//
118	// Kampagnen-Zuordnung für Anfragen – bewusst OHNE Cookies und OHNE Browserspeicher:
119	// Beim ersten Seitenaufruf werden UTM-Parameter, verweisende Domain und Einstiegsseite
120	// im Arbeitsspeicher der geöffneten Website gehalten (bleibt bei Navigation innerhalb der Seite
121	// erhalten, endet beim Schließen/Neuladen). Übertragen wird nur zusammen mit einer Anfrage.
122	
123	let erfasst = null;
124	
125	const UTM = ["utm_source", "utm_medium", "utm_campaign", "utm_term", "utm_content"];
126	const kurz = (v, n = 100) => String(v || "").replace(/[^\p{L}\p{N} _.\-/:+|]/gu, "").slice(0, n);
127	
128	function eigeneDomain(host) {
129	  return /(^|\.)oekoinvest\.(com|at|de|ch)$/.test(host) || host === location.host;
130	}
131	
132	/** Einmalig beim ersten Laden aufrufen (HerkunftErfassen in LayoutWrapper). */
133	export function herkunftErfassen() {
134	  if (typeof window === "undefined" || erfasst) return;
135	  const url = new URL(window.location.href);
136	  const utm = Object.fromEntries(UTM.map((k) => [k, kurz(url.searchParams.get(k))]).filter(([, v]) => v));
137	
138	  let referrer = "";
139	  try {
140	    const r = document.referrer ? new URL(document.referrer) : null;
141	    if (r && !eigeneDomain(r.host)) referrer = r.host.replace(/^www\./, "");
142	  } catch {
143	    /* ungültig */
144	  }
145	
146	  // Einmal-Tokens nie übernehmen
147	  const einstieg = url.pathname.replace(/^\/(scan|fortsetzen)\/.*/, "/$1").slice(0, 200);
148	  erfasst = { ...utm, referrer, einstieg, zeit: new Date().toISOString() };
149	}
150	
151	/** Kanal grob klassifizieren (für Auswertungen). */
152	function kanal(h) {
153	  const medium = (h.utm_medium || "").toLowerCase();
154	  if (h.utm_source || h.utm_medium) {
155	    if (/cpc|ppc|paid|ads?$/.test(medium)) return "Anzeige";
156	    if (/social/.test(medium)) return "Social Media";
157	    if (/mail|newsletter/.test(medium)) return "E-Mail";
158	    if (/qr|print|flyer|offline/.test(medium)) return "Offline/QR";
159	    return "Kampagne";
160	  }
161	  const r = h.referrer || "";
162	  if (!r) return "Direkt";
163	  if (/google\.|bing\.|duckduckgo\.|ecosia\.|yahoo\.|qwant\./.test(r)) return "Suchmaschine";
164	  if (/chatgpt\.com|openai\.com|perplexity\.ai|claude\.ai|gemini\.google|copilot\.microsoft/.test(r)) return "KI-Assistent";
165	  if (/facebook\.|instagram\.|linkedin\.|xing\.|t\.co$|x\.com|threads\.net|mastodon|social\.|youtube\./.test(r)) return "Social Media";
166	  return "Verweis";
167	}
168	
169	/** Daten zum Mitsenden mit einer Anfrage. `seite` = aktuelle Seite. */
170	export function herkunft() {
171	  if (typeof window === "undefined") return null;
172	  if (!erfasst) herkunftErfassen();
173	  const h = erfasst || {};
174	  return { ...h, kanal: kanal(h), seite: window.location.pathname.replace(/^\/(scan|fortsetzen)\/.*/, "/$1").slice(0, 200) };
175	}
176	
177	/** Kompakte Textzeile für Backends ohne eigene Felder (z. B. bestehende Kontaktanfrage). */
178	export function herkunftText(h = herkunft()) {
179	  if (!h) return "";
180	  const teile = [
181	    `Kanal: ${h.kanal}`,
182	    h.utm_source && `Quelle: ${h.utm_source}`,
183	    h.utm_medium && `Medium: ${h.utm_medium}`,
184	    h.utm_campaign && `Kampagne: ${h.utm_campaign}`,
185	    h.utm_term && `Keyword: ${h.utm_term}`,
186	    h.referrer && `Verweis: ${h.referrer}`,
187	    h.einstieg && `Einstieg: ${h.einstieg}`,
188	    h.seite && `Seite: ${h.seite}`,
189	  ].filter(Boolean);
190	  return `[Herkunft] ${teile.join(" · ")}`;
191	}
192	// Ereignisse für Google Analytics – werden nur gesendet, wenn der Besucher der Statistik zugestimmt hat
193	// (window.gtag existiert erst nach Einwilligung, siehe components/Statistik/GoogleAnalytics.js).
194	// Niemals personenbezogene Daten übergeben (keine Namen, E-Mails, Telefonnummern, Tokens).
195	
196	const ERLAUBT = /^[a-z0-9_]{2,40}$/;
197	
198	export function ereignis(name, daten) {
199	  if (typeof window === "undefined" || !ERLAUBT.test(name)) return;
200	  try {
201	    const sauber = daten
202	      ? Object.fromEntries(
203	          Object.entries(daten)
204	            .filter(([, v]) => ["string", "number", "boolean"].includes(typeof v))
205	            .map(([k, v]) => [k.slice(0, 40), typeof v === "string" ? v.slice(0, 80) : v])
206	        )
207	      : undefined;
208	    if (window.ovGaGeladen) window.gtag?.("event", name, sauber);
209	  } catch {
210	    /* Statistik darf nie stören */
211	  }
212	}

