 92	const OHNE = { essential: true, functional: false, googleMaps: false, statistics: false, googleAnalytics: false };
 93	
 94	export default function CookieBanner({ forceShow = false, onClose }) {
 95	  const router = useRouter();
 96	  const [isShown, setIsShown] = useState(false);
 97	  const [isCompact, setIsCompact] = useState(true);
 98	
 99	  const [showBanner, setShowBanner] = useState(forceShow);
100	  const [expandedSections, setExpandedSections] = useState({
101	    functional: false,
102	    statistics: false,
103	  });
104	  const [expandedServices, setExpandedServices] = useState({});
105	  const [consent, setConsent] = useState(OHNE);
106	
107	  useEffect(() => {
108	    const gespeichert = getCookie("cookieConsent");
109	    if (!gespeichert) {
110	      setShowBanner(true);
111	      return;
112	    }
113	    // Beim erneuten Öffnen die bisherige Auswahl anzeigen
114	    try {
115	      setConsent({ ...OHNE, ...JSON.parse(gespeichert), essential: true });
116	    } catch {
117	      /* ungültig -> Standard */
118	    }
119	  }, []);
120	
121	  useEffect(() => {
122	    setConsent((prev) => ({ ...prev, functional: prev.googleMaps, statistics: prev.googleAnalytics }));
123	  }, [consent.googleMaps, consent.googleAnalytics]);
124	
125	  const handleAcceptAll = () => {
126	    const newConsent = { essential: true, functional: true, googleMaps: true, statistics: true, googleAnalytics: true };
127	    setConsent(newConsent);
128	    saveConsent(newConsent);
129	    router.refresh();
130	  };
131	
132	  const handleAcceptSelected = () => {
133	    saveConsent(consent);
134	    router.refresh();
135	  };
136	
137	  const handleRejectAll = () => {
138	    const newConsent = OHNE;
139	    setConsent(newConsent);
140	    saveConsent(newConsent);
141	    router.refresh();
142	  };
143	
144	  const handleClose = () => {
145	    setShowBanner(false);
146	    if (onClose) onClose();
147	  };
148	
149	  const saveConsent = (consentState) => {
150	    setCookie("cookieConsent", JSON.stringify(consentState), {
151	      maxAge: 60 * 60 * 24 * 365,
152	      path: "/",
153	      sameSite: "lax",
154	    });
155	    // Google Analytics sofort (ohne Neuladen) starten bzw. stoppen
156	    window.dispatchEvent(new CustomEvent("ov-consent", { detail: consentState }));
157	
158	    // Close banner last
159	    setShowBanner(false);
160	    if (onClose) onClose();
161	  };
162	
163	  const toggleConsent = (category) => {
164	    setConsent((prev) => {
165	      const newConsent = { ...prev };
166	
167	      if (category === "functional") {
168	        const newValue = !prev.functional;
169	        newConsent.functional = newValue;
170	        newConsent.googleMaps = newValue;
171	      } else if (category === "statistics") {
172	        const newValue = !prev.statistics;
173	        newConsent.statistics = newValue;
174	        newConsent.googleAnalytics = newValue;
175	      } else {
176	        newConsent[category] = !prev[category];
177	      }
178	
179	      return newConsent;
180	    });
181	  };
182	
183	  const toggleCategoryDetails = (category) => {
184	    setExpandedSections((prev) => ({
185	      ...prev,
186	      [category]: !prev[category],
187	    }));
188	  };
189	
190	  const toggleServiceDetails = (service) => {
191	    setExpandedServices((prev) => ({
192	      ...prev,
193	      [service]: !prev[service],
194	    }));
195	  };
196	
197	  const toggleCompact = () => {
198	    setIsCompact(!isCompact);
199	    setIsShown(true);
200	  };
201	
202	  // Tastatur & Screenreader: Detailansicht ist ein modaler Dialog
203	  const sichtbar = forceShow || showBanner;
204	  const kompaktTitel = useRef(null);
205	  const individuellKnopf = useRef(null);
206	  const detailDialog = useRef(null);
207	  const detailTitel = useRef(null);
208	  useFokusFalle(sichtbar && !isCompact, detailDialog, {
209	    beiEscape: () => setIsCompact(true),
210	    startRef: detailTitel,
211	    rueckgabeRef: individuellKnopf,
212	  });
213	
214	  // Über „Privatsphäre-Einstellungen“ geöffnet: Fokus direkt in den Banner
215	  useEffect(() => {
216	    if (forceShow) kompaktTitel.current?.focus({ preventScroll: true });
217	  }, [forceShow]);
218	
219	  if (!sichtbar) return null;
220	  if (isCompact) {
221	    return (
222	      <div
223	        role="region"
224	        aria-label="Cookie-Einstellungen"
225	        className="ov-hero-in fixed inset-x-3 bottom-3 z-[9600] md:inset-x-auto md:bottom-6 md:left-6 md:max-w-[440px]"
226	      >
227	        <div className="rounded-3xl bg-white p-5 shadow-[0_30px_70px_-20px_rgba(3,18,43,0.45)] ring-1 ring-ink-200/70 md:p-6">
228	          <div className="flex items-start gap-3">
229	            <span aria-hidden="true" className="flex h-10 w-10 shrink-0 items-center justify-center rounded-2xl bg-ov-50 text-[20px]">🍪</span>
230	            <div>
231	              <h2 ref={kompaktTitel} tabIndex={-1} className="font-display text-[16.5px] font-bold text-ink-900 focus:outline-none">Ihre Privatsphäre zählt</h2>
232	              <p className="mt-1 text-[13.5px] leading-relaxed text-ink-600">
233	                Mit Ihrer Zustimmung nutzen wir Google Analytics für Besucherstatistiken.
234	                Ohne Zustimmung werden keine Daten an Google übertragen.
235	              </p>
236	            </div>
237	          </div>
238	          <div className="mt-5 grid grid-cols-2 gap-2">
239	            <button
240	              onClick={handleRejectAll}
241	              className="h-11 rounded-full px-3 text-[14px] font-semibold text-ink-800 ring-1 ring-inset ring-ink-200 transition-colors hover:bg-ink-50 cursor-pointer"
242	            >
243	              Nur notwendige
244	            </button>
245	            <button
246	              onClick={handleAcceptAll}
247	              className="h-11 rounded-full bg-ov-600 px-3 text-[14px] font-semibold text-white transition-colors hover:bg-ov-700 cursor-pointer"
248	            >
249	              Alle akzeptieren
250	            </button>
251	          </div>
252	          <button
253	            ref={individuellKnopf}
254	            onClick={toggleCompact}
255	            aria-haspopup="dialog"
256	            className="mt-3 w-full text-center text-[13px] font-medium text-ink-500 underline-offset-2 transition-colors hover:text-ink-800 hover:underline cursor-pointer"
257	          >
258	            Individuelle Einstellungen
259	          </button>
260	        </div>
261	      </div>
262	    );
263	  }
264	
265	  return (
