     3	// Kontext-Bauer je Anwendungsfall. Grundregel: ERST Rechte prüfen, DANN Kontext zusammenstellen.
     4	// Alle Daten kommen ausschließlich über die Backend-Operationen im Namen des angemeldeten Nutzers
     5	// (b.projekt, b.vorgang, b.flaeche, b.boerseDetail, b.nachrichten …) – diese prüfen Rolle UND
     6	// Eigentum selbst (Demo und Frappe). Was der Nutzer dort nicht sehen darf, kann nie in einen Prompt
     7	// gelangen. Zusätzlich gilt je Fall eine Positivliste der Felder (Datensparsamkeit: z. B. keine
     8	// E-Mail, Telefonnummer oder IP-Adresse im Prompt).
     9	//
    10	// Rückgabe: { objektArt, objektId, daten: {…}, quellen: [{ id, titel, text }], meta: {…} }
    11	
    12	import { PlattformFehler } from "../fehler";
    13	import { FLAECHE_NUTZUNG, LAENDER, NETZANSCHLUSS, PROJEKT_TYPEN, VORGANG_TYPEN, BEZUG_ARTEN, BEZUG_LABEL } from "../konstanten";
    14	import { PROZESSE, statusInfo } from "../prozesse";
    15	import { VERTRAULICH_FELDER } from "../oeffentlich";
    16	import { checklisteFlaeche } from "../checkliste";
    17	import { datum, feldLabel, preisText, wertText } from "../format";
    18	import { phaseById } from "@/lib/invest/markt";
    19	import { fmt } from "@/lib/rechner/annahmen";
    20	
    21	const KENNUNG = /^[A-Za-z0-9][A-Za-z0-9_-]{2,60}$/;
    22	
    23	export function kennungPruefen(id, was = "Objekt") {
    24	  const s = String(id || "").trim();
    25	  if (!KENNUNG.test(s)) throw new PlattformFehler(422, `${was} fehlt oder ist ungültig.`);
    26	  return s;
    27	}
    28	
    29	const kurzText = (s, max) => {
    30	  const t = String(s ?? "").replace(/\r/g, "").trim();
    31	  return t.length > max ? `${t.slice(0, max)} …` : t;
    32	};
    33	
    34	const nichtLeer = (o) => Object.fromEntries(Object.entries(o).filter(([, v]) => v !== undefined && v !== null && v !== "" && !(Array.isArray(v) && !v.length)));
    35	
    36	// ------------------------------------------------------------------ Exposé (Anbieter/Admin)
    37	
    38	/** Vertrauliche Felder, die als Einordnung dienen dürfen – nie Ortsbezug (Gemeinde, Flurstücke, Netzbetreiber, Einspeisepunkt) */
    39	const EXPOSE_VERTRAULICH_EINORDNUNG = ["sicherung", "planungsrecht", "ertragKwhKwp", "entfernungNetzKm", "verguetung"];
    40	
    41	export async function kontextExpose(b, n, { projektId }) {
    42	  const id = kennungPruefen(projektId, "Projekt");
    43	  const p = await b.projekt(n, id); // 404/403 bei fremdem Projekt (Backend prüft Eigentum)
    44	  const phase = p.phase ? phaseById(p.phase) : null;
    45	  const vt = p.vertraulich || {};
    46	  const erfuellt = (p.checkliste?.punkte || []).filter((x) => x.erwartet && x.vorhanden).map((x) => x.label);
    47	  const offen = (p.checkliste?.punkte || []).filter((x) => x.erwartet && x.pflicht && !x.vorhanden).map((x) => x.label);
    48	  return {
    49	    objektArt: "projekt",
    50	    objektId: p.id,
    51	    daten: nichtLeer({
    52	      projekttyp: PROJEKT_TYPEN[p.typ],
    53	      land: LAENDER[p.land],
    54	      bundeslandOderKanton: p.bundesland,
    55	      regionGrob: p.region,
    56	      leistungMwp: p.mwp,
    57	      speicherMwh: p.mwhSpeicher,
    58	      flaecheHa: p.flaecheHa,
    59	      phase: phase?.label,
    60	      typischesRisikoDerPhase: phase?.risiko,
    61	      netzanschluss: NETZANSCHLUSS[p.netzanschluss],
    62	      inbetriebnahmeGeplant: p.codGeplant,
    63	      preisindikation: preisText(p),
    64	      bisherigeBeschreibung: kurzText(p.beschreibung, 4000),
    65	      bisherigeHighlights: p.highlights,
    66	      einordnungIntern: nichtLeer(Object.fromEntries(EXPOSE_VERTRAULICH_EINORDNUNG.map((k) => [VERTRAULICH_FELDER[k], vt[k]]))),
    67	      unterlagenVorhanden: erfuellt,
    68	      unterlagenFehlend: offen,
    69	      datenraumQualitaetProzent: p.checkliste?.quote,
    70	    }),
    71	    quellen: [],
    72	    meta: { projekt: p },
    73	  };
    74	}
