    78	export async function kontextTriage(b, n, { vorgangId }) {
    79	  const id = kennungPruefen(vorgangId, "Vorgang");
    80	  const v = await b.vorgang(n, id);
    81	  const thread = await b.nachrichten(n, "vorgang", id, { markieren: false });
    82	  const k = v.kontakt || {};
    83	  const zusatz = Object.entries(v.daten || {})
    84	    .filter(([, x]) => x !== "" && x !== null && x !== undefined)
    85	    .map(([key, x]) => [feldLabel(key), kurzText(wertText(x), 1500)]);
    86	  const nachrichten = (thread?.nachrichten || [])
    87	    .filter((m) => !m.system)
    88	    .slice(-10)
    89	    .map((m) => ({ von: m.vonAdmin ? "Backoffice" : "Anfragende Person", am: datum(m.am), text: kurzText(m.text, 1500) }));
    90	  return {
    91	    objektArt: "vorgang",
    92	    objektId: v.id,
    93	    daten: nichtLeer({
    94	      vorgangsnummer: v.id,
    95	      typ: VORGANG_TYPEN[v.typ] || v.typ,
    96	      typSchluessel: v.typ,
    97	      status: statusInfo("vorgang", v.status).label,
    98	      eingegangenAm: datum(v.erstelltAm),
    99	      kontakt: nichtLeer({
   100	        anrede: k.anrede,
   101	        vorname: k.vorname,
   102	        nachname: k.nachname,
   103	        unternehmen: k.firma,
   104	        ort: [k.plz, k.ort].filter(Boolean).join(" "),
   105	        land: LAENDER[k.land],
   106	        telefonAngegeben: k.telefon ? "ja" : "nein",
   107	        kontoVorhanden: v.nutzer ? "ja" : "nein",
   108	      }),
   109	      angaben: Object.fromEntries(zusatz),
   110	      nachrichten,
   111	    }),
   112	    quellen: [],
   113	    meta: { vorgang: v, nachrichten: thread?.nachrichten || [] },
   114	  };
   115	}
