   119	export async function kontextFrage(b, n, { projektId }) {
   120	  const id = kennungPruefen(projektId, "Projekt");
   121	  const d = await b.boerseDetail(n, id, { zaehlen: false });
   122	  // Rechteprüfung VOR dem Zusammenstellen: nur mit freigegebenem Datenraum (NDA), als Anbieter oder Backoffice
   123	  if (!d || !["nda", "eigentuemer", "admin"].includes(d.zugriff)) {
   124	    throw new PlattformFehler(403, "„Frag das Projekt“ steht nach Freigabe Ihres Datenraums (NDA) zur Verfügung.", "verboten");
   125	  }
   126	  const p = d.projekt || {};
   127	  const phase = p.phase ? phaseById(p.phase) : null;
   128	  const quellen = [];
   129	  const q = (titel, text) => {
   130	    const t = String(text ?? "").trim();
   131	    if (!t) return;
   132	    quellen.push({ id: `Q${quellen.length + 1}`, titel, text: kurzText(t, 3000) });
   133	  };
   134	  q(
   135	    "Projektsteckbrief",
   136	    [
   137	      ["Projekttyp", PROJEKT_TYPEN[p.typ]],
   138	      ["Land", LAENDER[p.land]],
   139	      ["Bundesland/Kanton", p.bundesland],
   140	      ["Region", p.region],
   141	      ["Leistung", p.mwp ? `${fmt(p.mwp, 1)} MWp` : ""],
   142	      ["Speicher", p.mwhSpeicher ? `${fmt(p.mwhSpeicher)} MWh` : ""],
   143	      ["Fläche", p.flaecheHa ? `${fmt(p.flaecheHa, 1)} ha` : ""],
   144	      ["Phase", phase?.label],
   145	      ["Netzanschluss", NETZANSCHLUSS[p.netzanschluss]],
   146	      ["Geplante Inbetriebnahme", p.codGeplant],
   147	      ["Preisindikation", preisText(p)],
   148	      ["Datenraum-Qualität", typeof p.datenraumQualitaet === "number" ? `${p.datenraumQualitaet} %` : ""],
   149	    ]
   150	      .filter(([, w]) => w)
   151	      .map(([l, w]) => `${l}: ${w}`)
   152	      .join("\n")
   153	  );
   154	  q("Exposé – Beschreibung", p.beschreibung);
   155	  if (p.highlights?.length) q("Exposé – Highlights", p.highlights.map((h) => `- ${h}`).join("\n"));
   156	  for (const [k, label] of Object.entries(VERTRAULICH_FELDER)) {
   157	    const w = d.vertraulich?.[k];
   158	    if (w !== undefined && w !== null && w !== "") q(`Vertrauliche Angabe – ${label}`, String(w));
   159	  }
   160	  const doks = (d.dokumente || []).slice(0, 60);
   161	  if (doks.length) {
   162	    q(
   163	      "Datenraum – Dokumentenliste (nur Metadaten, Inhalte liegen nicht vor)",
   164	      doks.map((x) => `- ${x.name} · Kategorie ${x.kategorie}${x.checkliste ? ` · Checklistenpunkt ${x.checkliste}` : ""} · hochgeladen ${datum(x.am)}`).join("\n")
   165	    );
   166	  }
   167	  if (phase) q("ÖkoInvest-Marktdaten zur Phase (allgemein, nicht projektspezifisch)", `Übliche Preisspanne „${phase.label}“: ${fmt(phase.preisProKwp.min)}–${fmt(phase.preisProKwp.max)} €/kWp · typisches Risiko: ${phase.risiko}`);
   168	  return { objektArt: "projekt", objektId: p.id, daten: { projekttitel: p.titel }, quellen, meta: { zugriff: d.zugriff, projekt: p, interesseId: d.interesse?.id || null } };
   169	}
