export function pfadBereinigen(pfad) {
  let p = String(pfad || "").split(/[?#]/)[0] || "/";
  if (!p.startsWith("/")) p = `/${p}`;
  for (const [muster, ersatz] of ERSETZEN) {
    if (muster.test(p)) return p.replace(muster, ersatz);
  }
  if (!SICHERER_PFAD.test(p)) return "/";
  return p.slice(0, 200);
}

