  if (typeof v === "number") return Number.isFinite(v) ? v : undefined;
  if (typeof v === "boolean") return v;
  if (typeof v !== "string") return undefined;
  const t = v.trim().slice(0, 60);
  if (!t || VERDAECHTIG.some((re) => re.test(t))) return undefined;
  return t;
}

