export function parameterBereinigen(daten) {
  if (!daten || typeof daten !== "object") return {};
  const out = {};
  for (const [k, v] of Object.entries(daten)) {
    if (!PARAMETER_SET.has(k)) continue;
    const w = wertSauber(v);
    if (w !== undefined) out[k] = w;
