  try {
    if (!Object.prototype.hasOwnProperty.call(EREIGNISSE, name)) return false;
    if (!messungMoeglich()) return false;
    window.gtag("event", name, parameterBereinigen(daten));
    return true;
  } catch {
    return false; // Statistik darf nie stören
  }
}

